import{_ as n,o as t,c as s,a0 as o}from"./chunks/framework.Ckbw5VQO.js";const a="/geo-ml/documentation/learning/deep-learning/cnn/01_cnn.png",r="/geo-ml/documentation/learning/deep-learning/cnn/21_cnn.png",i="/geo-ml/documentation/learning/deep-learning/cnn/02_cnn.png",u="/geo-ml/documentation/learning/deep-learning/cnn/22_cnn.png",l="/geo-ml/documentation/learning/deep-learning/cnn/21_cnn.svg",v=JSON.parse('{"title":"Réseaux de neurones convolutifs (CNN)","description":"","frontmatter":{},"headers":[],"relativePath":"fr/learning/deep-learning/cnn/introduction.md","filePath":"fr/learning/deep-learning/cnn/introduction.md"}'),c={name:"fr/learning/deep-learning/cnn/introduction.md"};function d(p,e,g,m,h,q){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="reseaux-de-neurones-convolutifs-cnn" tabindex="-1">Réseaux de neurones convolutifs (CNN) <a class="header-anchor" href="#reseaux-de-neurones-convolutifs-cnn" aria-label="Permalink to &quot;Réseaux de neurones convolutifs (CNN)&quot;">​</a></h1><p>Les CNN sont une famille de réseaux de neurones conçus pour traiter des données organisées en <strong>grille</strong> : images (2D), vidéos (3D), signaux audio (1D). Ils sont la brique de base de quasiment toutes les tâches de computer vision.</p><img src="'+a+'" style="display:block;margin:0 auto;width:100%;height:auto;"><h2 id="qu-est-ce-qu-un-convolutional-neural-network" tabindex="-1">Qu’est-ce qu’un Convolutional Neural Network ? <a class="header-anchor" href="#qu-est-ce-qu-un-convolutional-neural-network" aria-label="Permalink to &quot;Qu’est-ce qu’un Convolutional Neural Network ?&quot;">​</a></h2><p>Un Convolutional Neural Networks est une architecture de réseau de neurones qui comprend généralement plusieurs couches de convolution.</p><img src="'+r+'" style="display:block;margin:0 auto;width:100%;height:auto;"><p>Les couches de convolution utilisent ce qu&#39;on appelle des &quot;filtres&quot; ou &quot;noyaux&quot; pour balayer l&#39;entrée (comme une image) et en extraire des caractéristiques spécifiques, telles que les bords, les textures, ou les formes. Chaque filtre est capable de détecter un type de caractéristique à différents endroits de l&#39;entrée.</p><h2 id="pourquoi-pas-un-reseau-classique" tabindex="-1">Pourquoi pas un réseau classique ? <a class="header-anchor" href="#pourquoi-pas-un-reseau-classique" aria-label="Permalink to &quot;Pourquoi pas un réseau classique ?&quot;">​</a></h2><p>Un réseau de neurones classique (ANN) connecte chaque neurone à tous ceux de la couche suivante. Sur une image 256×256 en RGB, ça donne <strong>196 608 entrées</strong>, et chaque connexion a un poids à apprendre. C&#39;est massif, lent, et surtout inutile : un pixel n&#39;a de sens que dans le contexte de ses voisins immédiats.</p><div class="tip custom-block"><p class="custom-block-title">Un CNN résout ce problème avec deux idées simples</p><ul><li><strong>Localité</strong> : un filtre ne regarde qu&#39;une petite zone à la fois (ex. 3×3 pixels)</li><li><strong>Partage de poids</strong> : le même filtre est appliqué partout sur l&#39;image</li></ul></div><img src="'+i+'" style="display:block;margin:0 auto;width:100%;height:auto;"><h2 id="composants-cles-d-un-cnn" tabindex="-1">Composants Clés d&#39;un CNN <a class="header-anchor" href="#composants-cles-d-un-cnn" aria-label="Permalink to &quot;Composants Clés d&#39;un CNN&quot;">​</a></h2><img src="'+u+'" style="display:block;margin:0 auto;width:100%;height:auto;"><h3 id="couches-de-convolution" tabindex="-1">Couches de convolution <a class="header-anchor" href="#couches-de-convolution" aria-label="Permalink to &quot;Couches de convolution&quot;">​</a></h3><p>Les couches de convolution sont le cœur d&#39;un CNN. Elles utilisent des <strong>filtres</strong> (petites matrices de poids) <strong>qui se déplacent sur l&#39;ensemble de l&#39;entrée</strong> (par exemple, une image) pour effectuer des <strong>opérations matricielles</strong>.</p><p>Chaque filtre détecte des caractéristiques spécifiques comme <strong>les bords, les angles ou d&#39;autres motifs visuels</strong> à partir de l&#39;entrée brute.</p><p>Le filtre applique une <strong>opération de convolution</strong> en prenant le produit scalaire entre le filtre et des portions locales de l&#39;entrée, créant ainsi une <strong>carte de caractéristiques pour chaque filtre</strong>. Cela permet de capturer des informations spatiales et de motif.</p><h3 id="fonction-d-activation-relu" tabindex="-1">Fonction d&#39;activation ReLU <a class="header-anchor" href="#fonction-d-activation-relu" aria-label="Permalink to &quot;Fonction d&#39;activation ReLU&quot;">​</a></h3><p>La <strong>Rectified Linear Unit (ReLU)</strong> est une fonction d&#39;activation couramment utilisée qui ajoute de la non-linéarité au réseau.</p><p>Sans non-linéarité, le réseau serait essentiellement un modèle linéaire, <strong>limité dans sa capacité à traiter des formes complexes</strong> de données.</p><p>ReLU <strong>transforme toutes les valeurs négatives en zéro</strong> et laisse les valeurs positives inchangées. Cela aide à accélérer la convergence du réseau lors de l&#39;apprentissage et à réduire le problème de disparition des gradients (où les gradients deviennent très petits, entravant l&#39;apprentissage).</p><h3 id="pooling-sous-echantillonnage" tabindex="-1">Pooling (sous-échantillonnage) <a class="header-anchor" href="#pooling-sous-echantillonnage" aria-label="Permalink to &quot;Pooling (sous-échantillonnage)&quot;">​</a></h3><p>La <strong>couche de pooling</strong>, souvent appelée aussi sous-échantillonnage, r<strong>éduit la dimensionnalité de chaque carte de caractéristiques</strong> tout en <strong>conservant les caractéristiques les plus importantes</strong>.</p><p>Les méthodes les plus courantes sont le <strong>max pooling et l&#39;average pooling</strong>. Le max pooling renvoie la valeur maximale d&#39;une portion de la carte de caractéristiques, tandis que l&#39;average pooling calcule la moyenne.</p><p>Cette <strong>réduction de dimensionnalité</strong> permet de diminuer la quantité de calculs et de poids dans le réseau, ce qui aide à combattre le surajustement (overfitting) et améliore la généralisation du modèle</p><h3 id="couches-entierement-connectees" tabindex="-1">Couches entièrement connectées <a class="header-anchor" href="#couches-entierement-connectees" aria-label="Permalink to &quot;Couches entièrement connectées&quot;">​</a></h3><p>Après plusieurs couches de convolution et de pooling, <strong>les cartes de caractéristiques sont aplanies</strong> et passées à des couches entièrement connectées, aussi connues sous le nom de couches denses.</p><p><strong>Ces couches combinent toutes les caractéristiques apprises</strong> par les couches précédentes pour effectuer la classification. Les neurones dans une couche dense ont des connexions complètes à tous les activations de la couche précédente, comme dans les réseaux de neurones traditionnels.</p><h2 id="l-architecture-typique" tabindex="-1">L&#39;architecture typique <a class="header-anchor" href="#l-architecture-typique" aria-label="Permalink to &quot;L&#39;architecture typique&quot;">​</a></h2><p>Un CNN enchaîne deux phases : l&#39;<strong>extraction de features</strong> (convolution → activation → pooling, répété N fois) puis la <strong>classification</strong> (couches denses + softmax).</p><img src="'+l+'" style="display:block;margin:0 auto;width:100%;height:auto;"><p><strong>Entrée</strong> : l&#39;image brute, un tenseur <code>H × W × C</code> (ex. 256×256×3 en RGB).</p><p><strong>Convolution</strong> : fait glisser N filtres 3×3 sur l&#39;entrée ; chacun produit une <em>feature map</em>.</p><p><strong>ReLU</strong> : <code>max(0, x)</code> sur chaque valeur. Supprime les négatifs et introduit la non-linéarité, sans laquelle empiler des couches ne servirait à rien.</p><p><strong>Pooling</strong> : réduit la résolution (ex. le max de chaque fenêtre 2×2). Allège le calcul et rend le réseau insensible aux petits décalages.</p><p><strong>Flatten + couches denses (<em>fully connected</em>)</strong> : aplatit les feature maps en un vecteur, puis connecte tous les neurones vers la sortie.</p><p><strong>Softmax</strong> : convertit les scores en probabilités par classe (somme = 1.0).</p><p><strong>Sortie</strong> : la classe prédite et son score de confiance.</p><div class="info custom-block"><p class="custom-block-title">CNN simple analysant une image pour détecter des visages.</p><p>La première couche de convolution pourrait capturer des détails basiques comme les bords, ensuite une couche de pooling pourrait réduire la dimensionnalité, puis une autre couche de convolution pourrait détecter des parties de visage comme les yeux ou la bouche, avant de passer à une couche de classification qui décide si l&#39;image contient un visage ou non.</p></div><h2 id="ce-que-le-cnn-apprend-couche-par-couche" tabindex="-1">Ce que le CNN apprend couche par couche <a class="header-anchor" href="#ce-que-le-cnn-apprend-couche-par-couche" aria-label="Permalink to &quot;Ce que le CNN apprend couche par couche&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Couche</th><th>Ce qu&#39;elle détecte</th></tr></thead><tbody><tr><td>1</td><td>Bords, gradients de couleur</td></tr><tr><td>2</td><td>Textures, motifs simples</td></tr><tr><td>3</td><td>Formes géométriques</td></tr><tr><td>Profondes</td><td>Objets complexes (couronne d&#39;arbre, fenêtre, toit…)</td></tr></tbody></table><p>Les premières couches sont génériques (détection de bords), les couches profondes sont spécifiques au domaine. C&#39;est pourquoi on peut <strong>réutiliser</strong> un CNN pré-entraîné sur une grande base d&#39;images et l&#39;adapter à une tâche spécifique (<em>transfer learning</em>).</p>',42)])])}const b=n(c,[["render",d]]);export{v as __pageData,b as default};
